package br.com.ajudamutua.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="webhook_events") public class WebhookEvent { @Id private UUID id; @Column(nullable=false,length=40) private String provider; @Column(nullable=false,unique=true,length=120) private String eventId; @Column(nullable=false,length=64) private String payloadSha256; @Column(nullable=false) private Instant eventTimestamp; @Column(nullable=false) private Instant receivedAt; @Column(nullable=false) private boolean processed; protected WebhookEvent(){} public WebhookEvent(UUID id,String provider,String eventId,String hash,Instant ts,Instant received){this.id=id;this.provider=provider;this.eventId=eventId;this.payloadSha256=hash;this.eventTimestamp=ts;this.receivedAt=received;} public void processed(){processed=true;} public String getEventId(){return eventId;} }
